/* Riverbend Regional Authority (Government) - source database seed for the pipeline Copy demo
   Plays the role of: Asset and works management system (on-prem SQL Server)
   Run this whole script ONCE in a Fabric SQL database (or Azure SQL / SQL Server). Then release the days in order:
       EXEC src.usp_release_day 1;   -- before the first pipeline run
       EXEC src.usp_release_day 2;   -- before the second run
       EXEC src.usp_release_day 3;   -- before the third run (adds a new column = schema drift)
   Generated by tools/build_kit.py - all data is fictional. */
IF SCHEMA_ID('src') IS NULL EXEC('CREATE SCHEMA src');
GO
DROP TABLE IF EXISTS src.public_assets; DROP TABLE IF EXISTS src.citizen_cases; DROP TABLE IF EXISTS src.stage_public_assets; DROP TABLE IF EXISTS src.stage_citizen_cases;
CREATE TABLE src.public_assets (asset_id INT NOT NULL, asset_ref NVARCHAR(30), asset_name NVARCHAR(100), asset_type NVARCHAR(30), district NVARCHAR(40), status NVARCHAR(30), criticality INT, replacement_value_kaud DECIMAL(12,1), constructed_date DATE, last_modified DATETIME2(0), CONSTRAINT pk_public_assets PRIMARY KEY (asset_id));
CREATE TABLE src.citizen_cases (case_id INT NOT NULL, asset_id INT, case_type NVARCHAR(30), priority INT, status NVARCHAR(30), lodged_ts DATETIME2(0), completed_ts DATETIME2(0), cost_aud DECIMAL(12,2), crew_hours DECIMAL(10,2), description NVARCHAR(200), last_modified DATETIME2(0), CONSTRAINT pk_citizen_cases PRIMARY KEY (case_id));
CREATE TABLE src.stage_public_assets (release_day INT NOT NULL, asset_id INT, asset_ref NVARCHAR(30), asset_name NVARCHAR(100), asset_type NVARCHAR(30), district NVARCHAR(40), status NVARCHAR(30), criticality INT, replacement_value_kaud DECIMAL(12,1), constructed_date DATE, last_modified DATETIME2(0), maintenance_contractor NVARCHAR(50));
CREATE TABLE src.stage_citizen_cases (release_day INT NOT NULL, case_id INT, asset_id INT, case_type NVARCHAR(30), priority INT, status NVARCHAR(30), lodged_ts DATETIME2(0), completed_ts DATETIME2(0), cost_aud DECIMAL(12,2), crew_hours DECIMAL(10,2), description NVARCHAR(200), last_modified DATETIME2(0));
GO
GO
CREATE OR ALTER PROCEDURE src.usp_release_day @day INT
AS
BEGIN
    SET NOCOUNT ON;
    IF @day >= 3 AND COL_LENGTH('src.public_assets', 'maintenance_contractor') IS NULL
        EXEC('ALTER TABLE src.public_assets ADD maintenance_contractor NVARCHAR(50) NULL');
    DELETE t FROM src.public_assets t WHERE EXISTS (SELECT 1 FROM src.stage_public_assets s WHERE s.release_day = @day AND s.asset_id = t.asset_id);
    IF @day >= 3
        EXEC('UPDATE t SET t.maintenance_contractor = s.maintenance_contractor FROM src.public_assets t JOIN src.stage_public_assets s ON s.asset_id = t.asset_id AND s.release_day = 3');
    DELETE t FROM src.citizen_cases t WHERE EXISTS (SELECT 1 FROM src.stage_citizen_cases s WHERE s.release_day = @day AND s.case_id = t.case_id);
    SELECT @day AS released_day, (SELECT COUNT(*) FROM src.public_assets) AS public_assets, (SELECT COUNT(*) FROM src.citizen_cases) AS citizen_cases;
END;
GO
